ST.xhtml:p:
Rtring_MiddleCylUp(CLK := bMiddleCylUp);
Rtring_MiddleCylDown(CLK := bMiddleCylDown);
Rtring_AutoControlM(CLK := g_bMiddleCylControlM);

IF Rtring_AutoControlM.Q THEN
  g_bMiddleCylControlM := FALSE;

  IF M.PARAMETER_Q[321] = 1.0 THEN
    bMiddleCylUp := TRUE;
    g_boMiddleCylinderUp := TRUE;
	g_boMiddleCylinderDown := FALSE;
  ELSE
    bMiddleCylDown := TRUE;
    g_boMiddleCylinderUp := FALSE;
    g_boMiddleCylinderDown := TRUE;
  END_IF;
END_IF;

IF Rtring_MiddleCylUp.Q THEN
  bMiddleCylUp := FALSE;
  g_boMiddleCylinderUp := TRUE;
  g_boMiddleCylinderDown := FALSE;
  bMiddleCylinderDelayFlag := TRUE;
  Ton_MiddleCyl1Alarm(IN := FALSE);
  bMiddleCylinderNoDownSignalAlarm := FALSE;
END_IF;

IF Rtring_MiddleCylDown.Q THEN
  bMiddleCylDown := FALSE;
  g_boMiddleCylinderUp := FALSE;
  g_boMiddleCylinderDown := TRUE;
  bMiddleCylinderDelayFlag := TRUE;
  Ton_MiddleCyl1Alarm(IN := FALSE);
  bMiddleCylinderNoUpSignalAlarm := FALSE;
END_IF;










(*hmi状态灯显示*)
IF bMiddleCylUseUpSignal AND g_boMiddleCylinderUp THEN(*使用到位信号*)
   bMiddleCylinderNoDownSignalAlarm := FALSE;
  IF NOT bPreIsUpStateCyl THEN
    IF bMiddleUpInPlace THEN
      g_bMiddleCylinderStateHmi:= TRUE;
      bPreIsUpStateCyl := TRUE;
      Ton_MiddleCyl1Alarm(IN := FALSE);
      bMiddleCylinderNoUpSignalAlarm := FALSE;
      M.ENABLE[321] := 0;
    ELSE
      Ton_MiddleCyl1Alarm(IN := g_boMiddleCylinderUp,PT := LREAL_TO_TIME(FUN_MStoS(nMiddleCylUpDoneTime)));
      IF Ton_MiddleCyl1Alarm.Q  THEN
        Ton_MiddleCyl1Alarm(IN := FALSE);
        bMiddleCylinderNoUpSignalAlarm := TRUE;
      END_IF;
    END_IF;
  ELSE
    IF bUpNoFilterInplace THEN
      bMiddleCylinderNoUpSignalAlarm := FALSE;
      M.ENABLE[321] := 0;
    ELSE
      bMiddleCylinderNoUpSignalAlarm := TRUE;
    END_IF; 
  END_IF;
ELSIF bMiddleCylUseDownSignal AND g_boMiddleCylinderDown THEN
   bMiddleCylinderNoUpSignalAlarm := FALSE;
  IF bPreIsUpStateCyl THEN
    IF bMiddleDownInPlace THEN
      g_bMiddleCylinderStateHmi:= FALSE;
      bPreIsUpStateCyl := FALSE;
      Ton_MiddleCyl1Alarm(IN := FALSE);
      bMiddleCylinderNoDownSignalAlarm := FALSE;
      M.ENABLE[321] := 0;
    ELSE
      Ton_MiddleCyl1Alarm(IN := g_boMiddleCylinderDown,PT := LREAL_TO_TIME(FUN_MStoS(nMiddleCylDownDoneTime)));
      IF Ton_MiddleCyl1Alarm.Q  THEN
        Ton_MiddleCyl1Alarm(IN := FALSE);
        bMiddleCylinderNoDownSignalAlarm := TRUE;
      END_IF;
    END_IF; 
  ELSE
    IF bDownNoFilterInplace THEN
      bMiddleCylinderNoDownSignalAlarm := FALSE;
      M.ENABLE[321] := 0;
    ELSE
      bMiddleCylinderNoDownSignalAlarm := TRUE;
    END_IF;
  END_IF;
ELSE(*使用延时信号*)
  bMiddleCylinderNoDownSignalAlarm := FALSE;
  bMiddleCylinderNoUpSignalAlarm := FALSE;
  IF bMiddleCylinderDelayFlag THEN
    IF g_boBlankingCyl01Up THEN
      Ton_Up(IN :=TRUE,PT := LREAL_TO_TIME(FUN_MStoS(nMiddleCylUpDoneTime)));
    ELSE
      Ton_Up(IN :=TRUE,PT := LREAL_TO_TIME(FUN_MStoS(nMiddleCylDownDoneTime)));
    END_IF;
    IF Ton_Up.Q THEN
       Ton_Up(IN :=FALSE);
      IF g_boMiddleCylinderUp AND g_boMiddleCylinderDown=FALSE THEN
        g_bMiddleCylinderStateHmi:= TRUE;
        bMiddleCylinderDelayFlag := FALSE;
        bPreIsUpStateCyl := TRUE;
        M.ENABLE[321] := 0;
      END_IF;
      IF g_boMiddleCylinderDown AND g_boMiddleCylinderUp=FALSE THEN
        g_bMiddleCylinderStateHmi:= FALSE;
        bMiddleCylinderDelayFlag := FALSE;
        bPreIsUpStateCyl := FALSE;
        M.ENABLE[321] := 0;
      END_IF;
    END_IF;
  END_IF;
END_IF;

IF bMiddleCylUseDownSignal AND NOT g_boMiddleCylinderUp AND NOT g_boMiddleCylinderDown THEN
  IF bDownNoFilterInplace THEN
    bMiddleCylinderNoDownSignalAlarm := FALSE;
  ELSE
    bMiddleCylinderNoDownSignalAlarm := TRUE;
  END_IF;
END_IF;

(*打开输出口控制 气缸使用延时的状态切换  182-183 零尾料气缸的状态切换*)
IF ArrayConfigOutputNumber[182] AND NOT bPreIsUpStateCyl THEN
  bPreIsUpStateCyl := TRUE;
  g_bMiddleCylinderStateHmi:= TRUE;
  ArrayConfigOutputNumber[182] := FALSE;
END_IF;  
IF ArrayConfigOutputNumber[183] AND bPreIsUpStateCyl THEN
  bPreIsUpStateCyl := FALSE;
  g_bMiddleCylinderStateHmi:= FALSE;
  ArrayConfigOutputNumber[183] := FALSE;
END_IF;  

IF bMiddleCylinderNoUpSignalAlarm THEN
  g_Alarm.alarmArray[572] := 1285;
ELSE
  g_Alarm.alarmArray[572] := 0;
END_IF;
IF bMiddleCylinderNoDownSignalAlarm THEN
  g_Alarm.alarmArray[573] := 1286;
ELSE
  g_Alarm.alarmArray[573] := 0;
END_IF;
Filter_Down(LREAL_TO_TIME(FUN_MSTOS(nMiddleCylFilterTime)),nMiddleCylDownSignalLogic,g_biMiddleCylinderDownSignal,bMiddleDownFilterSignal); 
bMiddleDownInPlace := FUN_SingalLogic(bMiddleDownFilterSignal,nMiddleCylDownSignalLogic);

Filter_Down20ms(LREAL_TO_TIME(FUN_MSTOS(20)),nMiddleCylDownSignalLogic,g_biMiddleCylinderDownSignal,bDownNoFilterInplace);




Filter_Up(LREAL_TO_TIME(FUN_MSTOS(nMiddleCylFilterTime)),nMiddleCylUpSignalLogic,g_biMiddleCylinderUpSignal,bMiddleUpFilterSignal); 
bMiddleUpInPlace := FUN_SingalLogic(bMiddleUpFilterSignal,nMiddleCylUpSignalLogic);

Filter_Up20ms(LREAL_TO_TIME(FUN_MSTOS(20)),nMiddleCylUpSignalLogic,g_biMiddleCylinderUpSignal,bUpNoFilterInplace);
